// Generated by scripts/build-production.js from src/primitives.js: the runtime without hot reloading or the DevTools hook. Do not edit.
// @zubra/runtime/primitives: the two keyboard behaviours the platform doesn't have.
//
// The platform now does most of what headless libraries used to: <dialog> traps focus and closes
// on Escape, `popover` gives a top layer and light dismissal, anchor positioning places it, and
// <details name> makes an exclusive group. What's left for menus, tab lists, toolbars and listboxes
// is moving focus among their items from the keyboard. Both functions here work on any element,
// in any framework, and return a cleanup:
//
//   onMount(() => rovingFocus(menu, { selector: '[role=menuitem]', orientation: 'vertical' }))
//   onMount(() => typeahead(menu, { selector: '[role=menuitem]' }))

const usable = (element) => !element.matches(':disabled, [aria-disabled=true], [hidden]') && element.getClientRects().length > 0;

/**
 * One tab stop for a group of items, with arrow keys (and Home and End) moving focus among them:
 * the WAI-ARIA "roving tabindex". The current item has tabindex 0 and the rest -1; focusing an
 * item (by a click, say) makes it current. Items are found again on each key, so a list that
 * changes needs nothing.
 *
 * - `selector`: the items, inside `container`;
 * - `orientation`: `vertical` (Up and Down), `horizontal` (Left and Right, flipped in RTL), or
 *   `both`;
 * - `loop`: from the last item, the next is the first (and back);
 * - `onMove(item)`: called after focus moves, for widgets whose selection follows focus (tabs).
 */
export function rovingFocus(container, { selector, orientation = 'both', loop = true, onMove } = {}) {
  if (!selector) throw new TypeError('rovingFocus: a `selector` for the items is needed');
  const items = () => [...container.querySelectorAll(selector)].filter(usable);
  const current = () => {
    const all = items();
    return all.find((item) => item.tabIndex === 0) ?? all.find((item) => item.matches('[aria-selected=true], [aria-checked=true], [aria-current]:not([aria-current=false])')) ?? all[0];
  };
  const make = (target) => {
    for (const item of container.querySelectorAll(selector)) item.tabIndex = item === target ? 0 : -1;
  };
  make(current());
  const keys = (event) => {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
    const all = items();
    const at = all.indexOf(event.target.closest?.(selector));
    if (at < 0) return;
    const rtl = getComputedStyle(container).direction === 'rtl';
    const next = { vertical: 'ArrowDown', horizontal: rtl ? 'ArrowLeft' : 'ArrowRight' };
    const previous = { vertical: 'ArrowUp', horizontal: rtl ? 'ArrowRight' : 'ArrowLeft' };
    const forward = orientation === 'both' ? [next.vertical, next.horizontal] : [next[orientation]];
    const back = orientation === 'both' ? [previous.vertical, previous.horizontal] : [previous[orientation]];
    let to;
    if (forward.includes(event.key)) to = at + 1 < all.length ? at + 1 : loop ? 0 : at;
    else if (back.includes(event.key)) to = at > 0 ? at - 1 : loop ? all.length - 1 : at;
    else if (event.key === 'Home') to = 0;
    else if (event.key === 'End') to = all.length - 1;
    else return;
    event.preventDefault();
    make(all[to]);
    all[to].focus();
    onMove?.(all[to]);
  };
  const focused = (event) => {
    const item = event.target.closest?.(selector);
    if (item && container.contains(item) && item.tabIndex !== 0) make(item);
  };
  container.addEventListener('keydown', keys);
  container.addEventListener('focusin', focused);
  return () => {
    container.removeEventListener('keydown', keys);
    container.removeEventListener('focusin', focused);
  };
}

/**
 * Type to jump: printable keys typed in quick succession are a prefix, and focus moves to the
 * next item (after the focused one, wrapping) whose text starts with it, ignoring case. Repeating
 * one letter cycles through the items that start with it.
 *
 * - `selector`: the items, inside `container`;
 * - `text(item)`: an item's text (its `textContent`, trimmed, by default);
 * - `timeout`: how long a pause ends the prefix, in milliseconds (500);
 * - `onMatch(item)`: called with the item instead of focusing it (for `aria-activedescendant`).
 */
export function typeahead(container, { selector, text = (item) => item.textContent.trim(), timeout = 500, onMatch } = {}) {
  if (!selector) throw new TypeError('typeahead: a `selector` for the items is needed');
  let typed = '';
  let timer = null;
  const keys = (event) => {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || event.key.length !== 1) return;
    if (event.key === ' ' && !typed) return; // Space activates, unless it's part of a prefix
    const all = [...container.querySelectorAll(selector)].filter(usable);
    if (!all.length) return;
    clearTimeout(timer);
    timer = setTimeout(() => (typed = ''), timeout);
    typed += event.key.toLowerCase();
    // "bbb" is "b" again, cycling.
    const prefix = typed.split('').every((letter) => letter === typed[0]) ? typed[0] : typed;
    const at = all.indexOf(document.activeElement?.closest?.(selector));
    const ordered = [...all.slice(at + 1), ...all.slice(0, at + 1)];
    const match = ordered.find((item) => text(item).toLowerCase().startsWith(prefix));
    if (!match) return;
    event.preventDefault();
    if (onMatch) onMatch(match);
    else match.focus();
  };
  container.addEventListener('keydown', keys);
  return () => {
    clearTimeout(timer);
    container.removeEventListener('keydown', keys);
  };
}
